use thinkthen::{Answer, Engine, Question};
let tt = Engine::from_env()?;

// a plain ask for money back is Yes. A thank-you is No
let ask = "Does the customer ask for a refund?";
for text in ["Please refund my order. It arrived broken.",
    "Thanks for the quick help yesterday!"] {
    println!("{:?}: {text}", tt.decide(ask, text)?);
}
